import java.util.Scanner;

public class CharacterCounter {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        System.out.println("Enter a sentence:");
        String str = sc.nextLine();

        int upper = 0, lower = 0, digits = 0, special = 0;

        for (int i = 0; i < str.length(); i++) {
            char ch = str.charAt(i);
            if (Character.isUpperCase(ch)) {
                upper++;
            } else if (Character.isLowerCase(ch)) {
                lower++;
            } else if (Character.isDigit(ch)) {
                digits++;
            } else if (!Character.isWhitespace(ch)) {
                special++;
            }
        }

        System.out.println("Uppercase letters: " + upper);
        System.out.println("Lowercase letters: " + lower);
        System.out.println("Digits: " + digits);
        System.out.println("Special characters: " + special);
    }
}
/*
VARIABLE DESCRIPTION TABLE:
Variable Name | Data Type | Purpose
str           | String    | Stores input sentence
upper         | int       | Frequency count of uppercase characters
lower         | int       | Frequency count of lowercase characters
digits        | int       | Frequency count of numerical digits
special       | int       | Frequency count of special symbols
i             | int       | Loop index for character traversal
ch            | char      | Extracted character at index i
*/
```

