import java.util.Scanner;

public class VowelFrequency {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        System.out.print("Enter a string in uppercase: ");
        String s = sc.nextLine().toUpperCase();

        int cA = 0, cE = 0, cI = 0, cO = 0, cU = 0;

        for (int i = 0; i < s.length(); i++) {
            char ch = s.charAt(i);
            switch (ch) {
                case 'A': cA++; break;
                case 'E': cE++; break;
                case 'I': cI++; break;
                case 'O': cO++; break;
                case 'U': cU++; break;
            }
        }

        System.out.println("Frequency of A: " + cA);
        System.out.println("Frequency of E: " + cE);
        System.out.println("Frequency of I: " + cI);
        System.out.println("Frequency of O: " + cO);
        System.out.println("Frequency of U: " + cU);
    }
}
